-- 0017: Seed the "BIOLOGIE 2015" exam paper (sujet) as a purchasable, playable quiz.
--
-- A "sujet" is a standalone quiz (no lesson, no mock exam) that a past_paper
-- shop_items row points at via reference_id. Students buy it in the Boutique
-- (faxcoins edge fn), then practise it freely (PaperQuiz -> /paper/:quizId).
--
-- Source of truth: the BIOLOGIE 2015 .docx, parsed by
-- scripts/parse_paper_docx.mjs (regenerate: node scripts/parse_paper_docx.mjs
-- "<docx>" --emit-migration). Idempotent: keyed by the fixed quiz id and the
-- shop item key, so re-runs and a fresh reset both converge.

-- 1) Allow a free-standing quiz (both FKs null) — papers belong to neither a
--    lesson nor a mock exam. Keep the mutual-exclusion guarantee.
alter table public.quizzes drop constraint if exists quizzes_target_check;
alter table public.quizzes add constraint quizzes_target_check
  check (not (lesson_id is not null and mock_exam_id is not null));

do $$
declare
  spec jsonb := $j${"paper":{"quizId":"b1015000-2015-4b15-a015-000000002015","title_fr":"BIOLOGIE 2015","title_en":"BIOLOGIE 2015","shopKey":"past-paper-biologie-2015","priceCoins":25},"questions":[{"difficulty":"medium","text_fr":"Quelle organelle est impliquée dans la production d’énergie d’une cellule procaryote ?","text_en":"Quelle organelle est impliquée dans la production d’énergie d’une cellule procaryote ?","explanation_fr":"Les procaryotes sont dépourvus d'organites membraneux (pas de mitochondries) ; leur production d'ATP s'effectue au niveau de la membrane plasmique.","explanation_en":"Les procaryotes sont dépourvus d'organites membraneux (pas de mitochondries) ; leur production d'ATP s'effectue au niveau de la membrane plasmique.","options":[{"text_fr":"Le chloroplaste","text_en":"Le chloroplaste","is_correct":false},{"text_fr":"Le noyau","text_en":"Le noyau","is_correct":false},{"text_fr":"La mitochondrie","text_en":"La mitochondrie","is_correct":false},{"text_fr":"Le réticulum endoplasmique","text_en":"Le réticulum endoplasmique","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":true}]},{"difficulty":"medium","text_fr":"Les tissus du corps sont organisés en","text_en":"Les tissus du corps sont organisés en","explanation_fr":"L'organisation biologique suit le niveau hiérarchique : cellules → tissus → organes → systèmes.","explanation_en":"L'organisation biologique suit le niveau hiérarchique : cellules → tissus → organes → systèmes.","options":[{"text_fr":"Cellules","text_en":"Cellules","is_correct":false},{"text_fr":"Systèmes corporels","text_en":"Systèmes corporels","is_correct":false},{"text_fr":"Organes","text_en":"Organes","is_correct":true},{"text_fr":"Organelles","text_en":"Organelles","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Laquelle des propositions suivantes distinguent les cellules eucaryotes des cellules procaryotes ?","text_en":"Laquelle des propositions suivantes distinguent les cellules eucaryotes des cellules procaryotes ?","explanation_fr":"Les cellules eucaryotes se définissent par la présence d'un noyau et d'organites entourés d'une membrane.","explanation_en":"Les cellules eucaryotes se définissent par la présence d'un noyau et d'organites entourés d'une membrane.","options":[{"text_fr":"La capacité à tolérer la présence d’oxygène","text_en":"La capacité à tolérer la présence d’oxygène","is_correct":false},{"text_fr":"La présence d’organelles liées par les membranes","text_en":"La présence d’organelles liées par les membranes","is_correct":true},{"text_fr":"La capacité à effectuer la photosynthèse","text_en":"La capacité à effectuer la photosynthèse","is_correct":false},{"text_fr":"La présence des ribosomes","text_en":"La présence des ribosomes","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Laquelle des structures ci-dessous ne sont pas retrouvée dans le noyau ?","text_en":"Laquelle des structures ci-dessous ne sont pas retrouvée dans le noyau ?","explanation_fr":"Les sous-unités ribosomiques sont assemblées dans le nucléole mais ne deviennent des ribosomes fonctionnels qu'une fois exportées dans le cytoplasme.","explanation_en":"Les sous-unités ribosomiques sont assemblées dans le nucléole mais ne deviennent des ribosomes fonctionnels qu'une fois exportées dans le cytoplasme.","options":[{"text_fr":"Les ribosomes fonctionnels","text_en":"Les ribosomes fonctionnels","is_correct":true},{"text_fr":"La chromatine se condensant en chromosomes","text_en":"La chromatine se condensant en chromosomes","is_correct":false},{"text_fr":"Le nucléole produisant l’ARN ribosomique","text_en":"Le nucléole produisant l’ARN ribosomique","is_correct":false},{"text_fr":"Le nucléoplasme au lieu de cytoplasme","text_en":"Le nucléoplasme au lieu de cytoplasme","is_correct":false},{"text_fr":"Toutes les réponses ci-dessus sont exactes","text_en":"Toutes les réponses ci-dessus sont exactes","is_correct":false}]},{"difficulty":"medium","text_fr":"La mitochondrie","text_en":"La mitochondrie","explanation_fr":"La mitochondrie contient des crêtes (replis de sa membrane interne) et des granules matriciels ; son rôle principal est d'effectuer la synthèse de l'ATP (respiration cellulaire).","explanation_en":"La mitochondrie contient des crêtes (replis de sa membrane interne) et des granules matriciels ; son rôle principal est d'effectuer la synthèse de l'ATP (respiration cellulaire).","options":[{"text_fr":"Poursuit la respiration cellulaire","text_en":"Poursuit la respiration cellulaire","is_correct":false},{"text_fr":"Décompose l’ATP pour produire l’énergie pour les cellules","text_en":"Décompose l’ATP pour produire l’énergie pour les cellules","is_correct":false},{"text_fr":"Contient les granules et les crêtes mitochondriales","text_en":"Contient les granules et les crêtes mitochondriales","is_correct":true},{"text_fr":"Toutes les réponses ci-dessus","text_en":"Toutes les réponses ci-dessus","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Pour les cellules où le dioxyde de carbone traverse la membrane plasmique par diffusion simple, qu’est-ce qui détermine la vitesse à laquelle le dioxyde de carbone pénètre dans la cellule ?","text_en":"Pour les cellules où le dioxyde de carbone traverse la membrane plasmique par diffusion simple, qu’est-ce qui détermine la vitesse à laquelle le dioxyde de carbone pénètre dans la cellule ?","explanation_fr":"La diffusion simple est un processus passif non véhiculé dont la vitesse dépend directement du gradient de concentration de la molécule.","explanation_en":"La diffusion simple est un processus passif non véhiculé dont la vitesse dépend directement du gradient de concentration de la molécule.","options":[{"text_fr":"La concentration du dioxyde de carbone de chaque côté de la membrane","text_en":"La concentration du dioxyde de carbone de chaque côté de la membrane","is_correct":true},{"text_fr":"La quantité d’ATP produit par la cellule","text_en":"La quantité d’ATP produit par la cellule","is_correct":false},{"text_fr":"La quantité de protéine porteuse dans la membrane","text_en":"La quantité de protéine porteuse dans la membrane","is_correct":false},{"text_fr":"La concentration d’ions hydrogènes de chaque côté de la membrane","text_en":"La concentration d’ions hydrogènes de chaque côté de la membrane","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Les protéines périphériques des membranes cellulaires","text_en":"Les protéines périphériques des membranes cellulaires","explanation_fr":"Liées par des liaisons électrostatiques non covalentes, les protéines périphériques se détachent facilement en modifiant la force ionique ou le pH du milieu sans détruire la bicouche lipidique.","explanation_en":"Liées par des liaisons électrostatiques non covalentes, les protéines périphériques se détachent facilement en modifiant la force ionique ou le pH du milieu sans détruire la bicouche lipidique.","options":[{"text_fr":"Peuvent être dissociées ioniquement sans rupture de la membrane","text_en":"Peuvent être dissociées ioniquement sans rupture de la membrane","is_correct":true},{"text_fr":"Sont seulement localisées au dehors de la membrane","text_en":"Sont seulement localisées au dehors de la membrane","is_correct":false},{"text_fr":"Sont aussi appelées les protéines transmembranaires sont les protéines porteuses des membranes cellulaires","text_en":"Sont aussi appelées les protéines transmembranaires sont les protéines porteuses des membranes cellulaires","is_correct":false},{"text_fr":"Toutes les réponses ci-dessus","text_en":"Toutes les réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Lequel des éléments suivants est une partie structurelle de la membrane cellulaire des eucaryotes ?","text_en":"Lequel des éléments suivants est une partie structurelle de la membrane cellulaire des eucaryotes ?","explanation_fr":"L'ossature fondamentale de la membrane plasmique est constituée d'une double couche de phospholipides.","explanation_en":"L'ossature fondamentale de la membrane plasmique est constituée d'une double couche de phospholipides.","options":[{"text_fr":"Les triglycérides","text_en":"Les triglycérides","is_correct":false},{"text_fr":"Les phospholipides","text_en":"Les phospholipides","is_correct":true},{"text_fr":"L’ATP","text_en":"L’ATP","is_correct":false},{"text_fr":"Plus d’un de ceux-ci-dessus","text_en":"Plus d’un de ceux-ci-dessus","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Laquelle des réponses suivantes décrit le mieux le transfert de l’ARN (tRNA) ?","text_en":"Laquelle des réponses suivantes décrit le mieux le transfert de l’ARN (tRNA) ?","explanation_fr":"L'ARN de transfert (ARNt) transporte les acides aminés spécifiques jusqu'au ribosome lors du processus de traduction.","explanation_en":"L'ARN de transfert (ARNt) transporte les acides aminés spécifiques jusqu'au ribosome lors du processus de traduction.","options":[{"text_fr":"Le processus par lequel l’ARN est assemblé à partir d’un brin d’ADN","text_en":"Le processus par lequel l’ARN est assemblé à partir d’un brin d’ADN","is_correct":false},{"text_fr":"L’attraction d’une protéine de liaison (agglutinante) et les autres facteurs de transcription pour informer la polymérase d’ARN où s’attacher et débuter la fabrication d’ARN","text_en":"L’attraction d’une protéine de liaison (agglutinante) et les autres facteurs de transcription pour informer la polymérase d’ARN où s’attacher et débuter la fabrication d’ARN","is_correct":false},{"text_fr":"L’enlèvement des introns du mRNA","text_en":"L’enlèvement des introns du mRNA","is_correct":false},{"text_fr":"L’addition étape par étape d’acides aminés à une chaîne croissante de polypeptide","text_en":"L’addition étape par étape d’acides aminés à une chaîne croissante de polypeptide","is_correct":true},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Laquelle des propositions suivantes est vraie pour la traduction dans les cellules humaines ?","text_en":"Laquelle des propositions suivantes est vraie pour la traduction dans les cellules humaines ?","explanation_fr":"La traduction du message de l'ARNm en chaîne polypeptidique s'effectue au niveau des complexes ribosomiques dans le cytoplasme.","explanation_en":"La traduction du message de l'ARNm en chaîne polypeptidique s'effectue au niveau des complexes ribosomiques dans le cytoplasme.","options":[{"text_fr":"Elle a lieu au niveau des ribosomes","text_en":"Elle a lieu au niveau des ribosomes","is_correct":true},{"text_fr":"Le mRNA est « lu » deux bases à la fois","text_en":"Le mRNA est « lu » deux bases à la fois","is_correct":false},{"text_fr":"Le processus a lieu avant la traduction","text_en":"Le processus a lieu avant la traduction","is_correct":false},{"text_fr":"La polymérase d’ADN est nécessaire pour la traduction","text_en":"La polymérase d’ADN est nécessaire pour la traduction","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"L’enzyme pepsine qui aide à digérer les protéines est produite et excrétée dans l’estomac. Laquelle des propositions suivantes serait vraie de l’enzyme ?","text_en":"L’enzyme pepsine qui aide à digérer les protéines est produite et excrétée dans l’estomac. Laquelle des propositions suivantes serait vraie de l’enzyme ?","explanation_fr":"Comme tout catalyseur biologique, la pepsine accélère la vitesse de réaction de dégradation des protéines qui serait autrement très lente.","explanation_en":"Comme tout catalyseur biologique, la pepsine accélère la vitesse de réaction de dégradation des protéines qui serait autrement très lente.","options":[{"text_fr":"L’enzyme fonctionne mieux à 100°C","text_en":"L’enzyme fonctionne mieux à 100°C","is_correct":false},{"text_fr":"L’enzyme fonctionne mieux à un pH neutre (pH 7)","text_en":"L’enzyme fonctionne mieux à un pH neutre (pH 7)","is_correct":false},{"text_fr":"L’enzyme est aussi utilisée pour digérer les hydrates de carbone","text_en":"L’enzyme est aussi utilisée pour digérer les hydrates de carbone","is_correct":false},{"text_fr":"Sans l’enzyme la digestion des protéines serait ralentie","text_en":"Sans l’enzyme la digestion des protéines serait ralentie","is_correct":true},{"text_fr":"L’enzyme est aussi utilisée pour digérer les lipides","text_en":"L’enzyme est aussi utilisée pour digérer les lipides","is_correct":false}]},{"difficulty":"medium","text_fr":"Quel est le nom utilisé pour désigner un produit chimique qui entre en compétition avec un substrat pour une place au site actif d’une enzyme ?","text_en":"Quel est le nom utilisé pour désigner un produit chimique qui entre en compétition avec un substrat pour une place au site actif d’une enzyme ?","explanation_fr":"Un inhibiteur compétitif possède une structure proche de celle du substrat et se fixe directement sur le site actif de l'enzyme.","explanation_en":"Un inhibiteur compétitif possède une structure proche de celle du substrat et se fixe directement sur le site actif de l'enzyme.","options":[{"text_fr":"Le groupe prosthétique","text_en":"Le groupe prosthétique","is_correct":false},{"text_fr":"L’inhibiteur réversible","text_en":"L’inhibiteur réversible","is_correct":false},{"text_fr":"L’inhibiteur compétitif","text_en":"L’inhibiteur compétitif","is_correct":true},{"text_fr":"L’inhibiteur du produit fini","text_en":"L’inhibiteur du produit fini","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Laquelle des propositions suivantes affecterait le moins l’efficacité d’une enzyme ?","text_en":"Laquelle des propositions suivantes affecterait le moins l’efficacité d’une enzyme ?","explanation_fr":"L'efficacité d'une enzyme dépend des conditions physiques (température, pH) et des concentrations de réactifs, mais la valeur de l'énergie d'activation sans catalyseur n'influence pas son fonctionnement.","explanation_en":"L'efficacité d'une enzyme dépend des conditions physiques (température, pH) et des concentrations de réactifs, mais la valeur de l'énergie d'activation sans catalyseur n'influence pas son fonctionnement.","options":[{"text_fr":"La température","text_en":"La température","is_correct":false},{"text_fr":"La concentration du substrat","text_en":"La concentration du substrat","is_correct":false},{"text_fr":"La concentration de l’enzyme","text_en":"La concentration de l’enzyme","is_correct":false},{"text_fr":"L’énergie d’activation originale du système","text_en":"L’énergie d’activation originale du système","is_correct":true},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Laquelle des propositions ci-dessous n’est pas vraie concernant l’inhibition d’enzyme ?","text_en":"Laquelle des propositions ci-dessous n’est pas vraie concernant l’inhibition d’enzyme ?","explanation_fr":"L'inhibiteur non-compétitif se fixe sur un site allostérique situé sur l'enzyme, et non pas sur le substrat.","explanation_en":"L'inhibiteur non-compétitif se fixe sur un site allostérique situé sur l'enzyme, et non pas sur le substrat.","options":[{"text_fr":"Dans l’inhibition compétitive, l’inhibiteur se lie avec le site actif de l’enzyme","text_en":"Dans l’inhibition compétitive, l’inhibiteur se lie avec le site actif de l’enzyme","is_correct":false},{"text_fr":"Dans l’inhibition non compétitive, l’inhibiteur se lie au site allostérique du substrat","text_en":"Dans l’inhibition non compétitive, l’inhibiteur se lie au site allostérique du substrat","is_correct":true},{"text_fr":"Dans l’inhibition irréversible, un poison se lie à l’enzyme de sorte qu’elle ne peut plus jamais fonctionner","text_en":"Dans l’inhibition irréversible, un poison se lie à l’enzyme de sorte qu’elle ne peut plus jamais fonctionner","is_correct":false},{"text_fr":"La plupart des inhibiteurs agissent de manière réversible","text_en":"La plupart des inhibiteurs agissent de manière réversible","is_correct":false},{"text_fr":"Les inhibiteurs compétitifs ressemblent habituellement le substrat","text_en":"Les inhibiteurs compétitifs ressemblent habituellement le substrat","is_correct":false}]},{"difficulty":"medium","text_fr":"Une molécule organique non protéique solidement liée au site actif d’une enzyme est :","text_en":"Une molécule organique non protéique solidement liée au site actif d’une enzyme est :","explanation_fr":"Un groupe prosthétique est un cofacteur non protéique fortement lié (souvent par des liaisons covalentes) à la partie protéique de l'enzyme.","explanation_en":"Un groupe prosthétique est un cofacteur non protéique fortement lié (souvent par des liaisons covalentes) à la partie protéique de l'enzyme.","options":[{"text_fr":"Une apoenzyme","text_en":"Une apoenzyme","is_correct":false},{"text_fr":"Une coenzyme","text_en":"Une coenzyme","is_correct":false},{"text_fr":"Une holoenzyme","text_en":"Une holoenzyme","is_correct":false},{"text_fr":"Un groupe prosthétique","text_en":"Un groupe prosthétique","is_correct":true},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Pour obtenir l’énergie de l’amidon et du glycogène, le corps doit commencer par","text_en":"Pour obtenir l’énergie de l’amidon et du glycogène, le corps doit commencer par","explanation_fr":"L'amidon et le glycogène sont des polystères (polymères de glucose) qui doivent être découpés en monomères de glucose avant de pouvoir entrer dans les voies cataboliques.","explanation_en":"L'amidon et le glycogène sont des polystères (polymères de glucose) qui doivent être découpés en monomères de glucose avant de pouvoir entrer dans les voies cataboliques.","options":[{"text_fr":"Hydrolyser l’amidon en glucose et en glycose","text_en":"Hydrolyser l’amidon en glucose et en glycose","is_correct":false},{"text_fr":"Hydrolyser aussi bien l’amidon et le glycogène en glucose","text_en":"Hydrolyser aussi bien l’amidon et le glycogène en glucose","is_correct":true},{"text_fr":"Convertir aussi bien l’amidon et le glycogène en acide gras","text_en":"Convertir aussi bien l’amidon et le glycogène en acide gras","is_correct":false},{"text_fr":"Enlever les atomes d’azote de deux molécules","text_en":"Enlever les atomes d’azote de deux molécules","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Lesquelles des propositions suivantes sont des organelles qui fonctionnent dans la conversion de l’énergie en une forme chimiquement utilisable dans les cellules ?","text_en":"Lesquelles des propositions suivantes sont des organelles qui fonctionnent dans la conversion de l’énergie en une forme chimiquement utilisable dans les cellules ?","explanation_fr":"La mitochondrie (respiration) et le chloroplaste (photosynthèse) sont deux organites clés dans les transformations énergétiques de la cellule (production d'ATP).","explanation_en":"La mitochondrie (respiration) et le chloroplaste (photosynthèse) sont deux organites clés dans les transformations énergétiques de la cellule (production d'ATP).","options":[{"text_fr":"Réticulum endoplasmique","text_en":"Réticulum endoplasmique","is_correct":false},{"text_fr":"Mitochondrie","text_en":"Mitochondrie","is_correct":false},{"text_fr":"Chloroplaste","text_en":"Chloroplaste","is_correct":false},{"text_fr":"B et C à la fois","text_en":"B et C à la fois","is_correct":true},{"text_fr":"A et B la fois","text_en":"A et B la fois","is_correct":false}]},{"difficulty":"medium","text_fr":"Citez deux produits de la respiration aérobique qui sont considéré comme des déchets","text_en":"Citez deux produits de la respiration aérobique qui sont considéré comme des déchets","explanation_fr":"L'équation bilan globale est : (C6H12O6 + 6(O2) → 6CO2 + 6H2O + ATP. Le CO2 et l'H2O sont éliminés comme sous-produits.","explanation_en":"L'équation bilan globale est : (C6H12O6 + 6(O2) → 6CO2 + 6H2O + ATP. Le CO2 et l'H2O sont éliminés comme sous-produits.","options":[{"text_fr":"Carbone et oxygène","text_en":"Carbone et oxygène","is_correct":false},{"text_fr":"Dioxyde de carbone et acide carbonique","text_en":"Dioxyde de carbone et acide carbonique","is_correct":false},{"text_fr":"Dioxyde de carbone et vapeur d’eau","text_en":"Dioxyde de carbone et vapeur d’eau","is_correct":true},{"text_fr":"Acide lactique et alcool","text_en":"Acide lactique et alcool","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Laquelle des propositions suivantes produit de l’ATP par une phosphorylation du substrat ?","text_en":"Laquelle des propositions suivantes produit de l’ATP par une phosphorylation du substrat ?","explanation_fr":"Lors de la glycolyse, des liaisons à haute énergie présentes sur des intermédiaires métaboliques permettent le transfert direct d'un groupe phosphate vers l'ADP pour former de l'ATP.","explanation_en":"Lors de la glycolyse, des liaisons à haute énergie présentes sur des intermédiaires métaboliques permettent le transfert direct d'un groupe phosphate vers l'ADP pour former de l'ATP.","options":[{"text_fr":"La glycolyse","text_en":"La glycolyse","is_correct":true},{"text_fr":"Le cycle de Krebs","text_en":"Le cycle de Krebs","is_correct":false},{"text_fr":"Le système de transport d’électron","text_en":"Le système de transport d’électron","is_correct":false},{"text_fr":"Le cycle de Calvin","text_en":"Le cycle de Calvin","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Les contractions qui propulsent la nourriture en avant dans le tube digestif sont appelées :","text_en":"Les contractions qui propulsent la nourriture en avant dans le tube digestif sont appelées :","explanation_fr":"Le péristaltisme désigne la succession de vagues de contractions musculaires lisses conduisant le bol alimentaire le long du tractus digestif.","explanation_en":"Le péristaltisme désigne la succession de vagues de contractions musculaires lisses conduisant le bol alimentaire le long du tractus digestif.","options":[{"text_fr":"Chyme","text_en":"Chyme","is_correct":false},{"text_fr":"Péristaltisme","text_en":"Péristaltisme","is_correct":true},{"text_fr":"Reflux","text_en":"Reflux","is_correct":false},{"text_fr":"Amylase","text_en":"Amylase","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Lorsque le pyruvate est converti en acétyle-CoA, lesquelles des substances suivantes sont aussi produites ?","text_en":"Lorsque le pyruvate est converti en acétyle-CoA, lesquelles des substances suivantes sont aussi produites ?","explanation_fr":"La décarboxylation oxydative du pyruvate génère 1NADH, H+ et 1 molécule de CO2 par molécule de pyruvate.","explanation_en":"La décarboxylation oxydative du pyruvate génère 1NADH, H+ et 1 molécule de CO2 par molécule de pyruvate.","options":[{"text_fr":"NADH et dioxyde de carbone sont fabriqués","text_en":"NADH et dioxyde de carbone sont fabriqués","is_correct":true},{"text_fr":"NADH et ATP sont fabriqués","text_en":"NADH et ATP sont fabriqués","is_correct":false},{"text_fr":"Dioxyde de carbone et ATP sont fabriqués","text_en":"Dioxyde de carbone et ATP sont fabriqués","is_correct":false},{"text_fr":"NADH est fabriqué","text_en":"NADH est fabriqué","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Laquelle des propositions suivantes est l’objet principal du processus qu’on appelle respiration cellulaire ?","text_en":"Laquelle des propositions suivantes est l’objet principal du processus qu’on appelle respiration cellulaire ?","explanation_fr":"La fonction essentielle de la respiration cellulaire est la conversion de l'énergie chimique des nutriments en énergie utilisable sous forme d'ATP.","explanation_en":"La fonction essentielle de la respiration cellulaire est la conversion de l'énergie chimique des nutriments en énergie utilisable sous forme d'ATP.","options":[{"text_fr":"Produire l’ATP","text_en":"Produire l’ATP","is_correct":true},{"text_fr":"Produire des molécules réduites de NAD","text_en":"Produire des molécules réduites de NAD","is_correct":false},{"text_fr":"Décomposer le glucose","text_en":"Décomposer le glucose","is_correct":false},{"text_fr":"Fermenter l’alcool","text_en":"Fermenter l’alcool","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Laquelle des propositions suivantes produit un déchet appelé acide lactique ?","text_en":"Laquelle des propositions suivantes produit un déchet appelé acide lactique ?","explanation_fr":"En l'absence d'oxygène, le muscle squelettique effectue la fermentation lactique qui réduit le pyruvate en acide lactique (lactate).","explanation_en":"En l'absence d'oxygène, le muscle squelettique effectue la fermentation lactique qui réduit le pyruvate en acide lactique (lactate).","options":[{"text_fr":"La glycolyse","text_en":"La glycolyse","is_correct":false},{"text_fr":"La respiration anaérobie dans les cellules musculaires humaines","text_en":"La respiration anaérobie dans les cellules musculaires humaines","is_correct":true},{"text_fr":"La respiration aérobie dans les cellules musculaires humaines","text_en":"La respiration aérobie dans les cellules musculaires humaines","is_correct":false},{"text_fr":"La fermentation d’alcool","text_en":"La fermentation d’alcool","is_correct":false},{"text_fr":"Toutes les réponses ci-dessus","text_en":"Toutes les réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Le processus connu comme glycolyse a lieu dans quelle partie de la cellule ?","text_en":"Le processus connu comme glycolyse a lieu dans quelle partie de la cellule ?","explanation_fr":"Les enzymes impliquées dans la glycolyse se trouvent dissoutes dans le cytosol (hyaloplasme).","explanation_en":"Les enzymes impliquées dans la glycolyse se trouvent dissoutes dans le cytosol (hyaloplasme).","options":[{"text_fr":"Dans le noyau","text_en":"Dans le noyau","is_correct":false},{"text_fr":"Dans le cytoplasme liquide","text_en":"Dans le cytoplasme liquide","is_correct":true},{"text_fr":"Dans la mitochondrie","text_en":"Dans la mitochondrie","is_correct":false},{"text_fr":"Dans la surface extrême de la mitochondrie","text_en":"Dans la surface extrême de la mitochondrie","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Quelle partie de la respiration aérobie produit la quantité la plus importante d’ATP ?","text_en":"Quelle partie de la respiration aérobie produit la quantité la plus importante d’ATP ?","explanation_fr":"La chaîne de transport des électrons couplée à la phosphorylation oxydative fournit la plus grande quantité d'ATP (̴ 28 à 32 ATP).","explanation_en":"La chaîne de transport des électrons couplée à la phosphorylation oxydative fournit la plus grande quantité d'ATP (̴ 28 à 32 ATP).","options":[{"text_fr":"La chaîne de transport d’électron","text_en":"La chaîne de transport d’électron","is_correct":true},{"text_fr":"Le cycle de Krebs","text_en":"Le cycle de Krebs","is_correct":false},{"text_fr":"La fermentation alcoolique","text_en":"La fermentation alcoolique","is_correct":false},{"text_fr":"La fermentation d’acide lactique","text_en":"La fermentation d’acide lactique","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Quel rôle joue le système nerveux dans la digestion ?","text_en":"Quel rôle joue le système nerveux dans la digestion ?","explanation_fr":"Le système nerveux végétatif (notamment le système parasympathique) stimule les sécrétions exocrines (salive, HCl) et endocrines digestives.","explanation_en":"Le système nerveux végétatif (notamment le système parasympathique) stimule les sécrétions exocrines (salive, HCl) et endocrines digestives.","options":[{"text_fr":"Il stimule les neurones moteurs à emmener les impulsions du cerveau et de la moelle épinière","text_en":"Il stimule les neurones moteurs à emmener les impulsions du cerveau et de la moelle épinière","is_correct":false},{"text_fr":"Il stimule la sécrétion de la salive, des acides de l’estomac et des hormones","text_en":"Il stimule la sécrétion de la salive, des acides de l’estomac et des hormones","is_correct":true},{"text_fr":"Il stimule le pacemaker à accélérer ou à ralentir","text_en":"Il stimule le pacemaker à accélérer ou à ralentir","is_correct":false},{"text_fr":"Il régule la respiration","text_en":"Il régule la respiration","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Les deux divisions du système nerveux autonome sont","text_en":"Les deux divisions du système nerveux autonome sont","explanation_fr":"Le système nerveux végétatif autonome est séparé en deux composantes aux actions antagonistes : le système sympathique et le système parasympathique.","explanation_en":"Le système nerveux végétatif autonome est séparé en deux composantes aux actions antagonistes : le système sympathique et le système parasympathique.","options":[{"text_fr":"Parasympathique et somatique","text_en":"Parasympathique et somatique","is_correct":false},{"text_fr":"Symphéral et somatique","text_en":"Symphéral et somatique","is_correct":false},{"text_fr":"Périphérique et parasympathique","text_en":"Périphérique et parasympathique","is_correct":false},{"text_fr":"Sympathique et parasympathique","text_en":"Sympathique et parasympathique","is_correct":true},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Le sens de l’équilibre est logé dans :","text_en":"Le sens de l’équilibre est logé dans :","explanation_fr":"Situé dans l'oreille interne, le système vestibulaire (canaux semi-circulaires, utricule, saccule) est le centre récepteur de l'équilibre.","explanation_en":"Situé dans l'oreille interne, le système vestibulaire (canaux semi-circulaires, utricule, saccule) est le centre récepteur de l'équilibre.","options":[{"text_fr":"L’oreille moyenne","text_en":"L’oreille moyenne","is_correct":false},{"text_fr":"L’appareil vestibulaire","text_en":"L’appareil vestibulaire","is_correct":true},{"text_fr":"L’oreille externe","text_en":"L’oreille externe","is_correct":false},{"text_fr":"Les osselets de l’oreille","text_en":"Les osselets de l’oreille","is_correct":false},{"text_fr":"Toutes réponses ci-dessus","text_en":"Toutes réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Pour que les rayons lumineux tombent sur la rétine sous des conditions normales","text_en":"Pour que les rayons lumineux tombent sur la rétine sous des conditions normales","explanation_fr":"Pour accommoder la vision à distance, le muscle ciliaire se relâche, ce qui tend les zonules et amincit le cristal (lentille).","explanation_en":"Pour accommoder la vision à distance, le muscle ciliaire se relâche, ce qui tend les zonules et amincit le cristal (lentille).","options":[{"text_fr":"Le globe oculaire doit augmenter en diamètre","text_en":"Le globe oculaire doit augmenter en diamètre","is_correct":false},{"text_fr":"La lentille doit s’amincir","text_en":"La lentille doit s’amincir","is_correct":true},{"text_fr":"Tous les bâtonnets doivent être activés","text_en":"Tous les bâtonnets doivent être activés","is_correct":false},{"text_fr":"Tous les cônes doivent être activés","text_en":"Tous les cônes doivent être activés","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Laquelle des structures suivantes convertissent les vibrations du son en impulsions nerveuses ?","text_en":"Laquelle des structures suivantes convertissent les vibrations du son en impulsions nerveuses ?","explanation_fr":"La cochlée renferme l'organe de Corti dont les cellules ciliées transforment l'onde mécanique en signal nerveux électrique.","explanation_en":"La cochlée renferme l'organe de Corti dont les cellules ciliées transforment l'onde mécanique en signal nerveux électrique.","options":[{"text_fr":"La cochlée","text_en":"La cochlée","is_correct":true},{"text_fr":"Le tympan","text_en":"Le tympan","is_correct":false},{"text_fr":"Les os de l’oreille","text_en":"Les os de l’oreille","is_correct":false},{"text_fr":"Le nerf auditif","text_en":"Le nerf auditif","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Le terme qui décrit le mieux l’hormone embryonnaire qui maintient la sécrétion de la progestérone et de l’œstrogène par le corps jaune (pendant le premier trimestre de la grossesse) est :","text_en":"Le terme qui décrit le mieux l’hormone embryonnaire qui maintient la sécrétion de la progestérone et de l’œstrogène par le corps jaune (pendant le premier trimestre de la grossesse) est :","explanation_fr":"L'hCG sécrétée par le tissu trophoblastique maintient le corps jaune en activité au cours du début de la gestation.","explanation_en":"L'hCG sécrétée par le tissu trophoblastique maintient le corps jaune en activité au cours du début de la gestation.","options":[{"text_fr":"L’hormone lutéinisante (LH)","text_en":"L’hormone lutéinisante (LH)","is_correct":false},{"text_fr":"La progestérone","text_en":"La progestérone","is_correct":false},{"text_fr":"La gonadotrophine chorionique humaine","text_en":"La gonadotrophine chorionique humaine","is_correct":true},{"text_fr":"La gonadotrophine releasing hormone (GnRH)","text_en":"La gonadotrophine releasing hormone (GnRH)","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Laquelle des propositions suivantes est incorrectement appariée avec sa fonction ?","text_en":"Laquelle des propositions suivantes est incorrectement appariée avec sa fonction ?","explanation_fr":"Les tubules séminifères sont le site de production des spermatozoïdes ; ce sont les vésicules séminales qui apportent le fluide contenant le fructose et les prostaglandines.","explanation_en":"Les tubules séminifères sont le site de production des spermatozoïdes ; ce sont les vésicules séminales qui apportent le fluide contenant le fructose et les prostaglandines.","options":[{"text_fr":"Tubules séminifères – ajoutent du liquide contenant du mucus, du fructose et de la prostaglandine aux spermes","text_en":"Tubules séminifères – ajoutent du liquide contenant du mucus, du fructose et de la prostaglandine aux spermes","is_correct":true},{"text_fr":"Scrotum – enferme les testicules tenus au-dessus de la cavité abdominale","text_en":"Scrotum – enferme les testicules tenus au-dessus de la cavité abdominale","is_correct":false},{"text_fr":"Épididyme – emmagasine le sperme","text_en":"Épididyme – emmagasine le sperme","is_correct":false},{"text_fr":"Glande prostatique – ajoute la sécrétion alcaline au sperme","text_en":"Glande prostatique – ajoute la sécrétion alcaline au sperme","is_correct":false},{"text_fr":"Aucune des propositions ci-dessus n’est appariée de manière incorrecte","text_en":"Aucune des propositions ci-dessus n’est appariée de manière incorrecte","is_correct":false}]},{"difficulty":"medium","text_fr":"Au cours du cycle menstruel, quelle est la source principale de progestérone chez les femmes ?","text_en":"Au cours du cycle menstruel, quelle est la source principale de progestérone chez les femmes ?","explanation_fr":"Après l'ovulation, la structure folliculaire restante se transforme en corps jaune pour assurer la sécrétion hormonale de progestérone.","explanation_en":"Après l'ovulation, la structure folliculaire restante se transforme en corps jaune pour assurer la sécrétion hormonale de progestérone.","options":[{"text_fr":"Le cortex surrénalien","text_en":"Le cortex surrénalien","is_correct":false},{"text_fr":"L’hypophyse antérieure","text_en":"L’hypophyse antérieure","is_correct":false},{"text_fr":"Le corps jaune","text_en":"Le corps jaune","is_correct":true},{"text_fr":"L’utérus","text_en":"L’utérus","is_correct":false},{"text_fr":"L’ovaire","text_en":"L’ovaire","is_correct":false}]},{"difficulty":"medium","text_fr":"Quelles sont les trois phases du cycle ovarien ?","text_en":"Quelles sont les trois phases du cycle ovarien ?","explanation_fr":"Le cycle de l'ovaire comporte successivement la phase de développement du follicule (folliculaire), la ponte ovulaire (ovulatoire) et la phase lutéale.","explanation_en":"Le cycle de l'ovaire comporte successivement la phase de développement du follicule (folliculaire), la ponte ovulaire (ovulatoire) et la phase lutéale.","options":[{"text_fr":"Embryon, fœtus et nouveau-né","text_en":"Embryon, fœtus et nouveau-né","is_correct":false},{"text_fr":"Première, deuxième et troisième trimestre","text_en":"Première, deuxième et troisième trimestre","is_correct":false},{"text_fr":"Menstruelle, proliférative et sécrétoire","text_en":"Menstruelle, proliférative et sécrétoire","is_correct":false},{"text_fr":"Folliculaire, ovulatoire et lutéale","text_en":"Folliculaire, ovulatoire et lutéale","is_correct":true},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"L’hormone hypophysaire antérieure qui stimule la maturation du follicule dans l’ovaire au cours du début du cycle menstruel est :","text_en":"L’hormone hypophysaire antérieure qui stimule la maturation du follicule dans l’ovaire au cours du début du cycle menstruel est :","explanation_fr":"La FSH (hormone folliculo-stimulante) produite par l'antéhypophyse stimule le recrutement et la croissance des follicules ovariens.","explanation_en":"La FSH (hormone folliculo-stimulante) produite par l'antéhypophyse stimule le recrutement et la croissance des follicules ovariens.","options":[{"text_fr":"L’hormone lutéinisante (LH)","text_en":"L’hormone lutéinisante (LH)","is_correct":false},{"text_fr":"La follicule stimulating hormone (FSH)","text_en":"La follicule stimulating hormone (FSH)","is_correct":true},{"text_fr":"Le Gonadotrophin releasing hormone (GnRH)","text_en":"Le Gonadotrophin releasing hormone (GnRH)","is_correct":false},{"text_fr":"Les œstrogènes","text_en":"Les œstrogènes","is_correct":false},{"text_fr":"La progestérone","text_en":"La progestérone","is_correct":false}]},{"difficulty":"medium","text_fr":"En général, la............... du cycle de vie cellulaire requiert le moins de temps :","text_en":"En général, la............... du cycle de vie cellulaire requiert le moins de temps :","explanation_fr":"La phase M de division cellulaire (mitose) dure généralement très peu de temps (1 à 2 heures) en comparaison des phases d'interphase (G1, S, G2).","explanation_en":"La phase M de division cellulaire (mitose) dure généralement très peu de temps (1 à 2 heures) en comparaison des phases d'interphase (G1, S, G2).","options":[{"text_fr":"Phase G1","text_en":"Phase G1","is_correct":false},{"text_fr":"Phase G2","text_en":"Phase G2","is_correct":false},{"text_fr":"Phase S","text_en":"Phase S","is_correct":false},{"text_fr":"Phase M (division)","text_en":"Phase M (division)","is_correct":true},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"La phase la plus longue de la mitose est laquelle parmi celles-ci ?","text_en":"La phase la plus longue de la mitose est laquelle parmi celles-ci ?","explanation_fr":"La prophase requiert le plus de temps pour condenser les chromosomes, désorganiser le noyau et construire le fuseau mitotique.","explanation_en":"La prophase requiert le plus de temps pour condenser les chromosomes, désorganiser le noyau et construire le fuseau mitotique.","options":[{"text_fr":"La prophase","text_en":"La prophase","is_correct":true},{"text_fr":"La métaphase","text_en":"La métaphase","is_correct":false},{"text_fr":"L’anaphase","text_en":"L’anaphase","is_correct":false},{"text_fr":"La télophase","text_en":"La télophase","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Au cours de la méiose, le nombre diploïde de chromosomes est réduit au nombre haploïde dans","text_en":"Au cours de la méiose, le nombre diploïde de chromosomes est réduit au nombre haploïde dans","explanation_fr":"La méiose réduit le stock chromosomique de $2n$ à $n$ lors de la formation de tous les gamètes (mâles et femelles).","explanation_en":"La méiose réduit le stock chromosomique de $2n$ à $n$ lors de la formation de tous les gamètes (mâles et femelles).","options":[{"text_fr":"Les ovules seulement","text_en":"Les ovules seulement","is_correct":false},{"text_fr":"Les corps polaires seulement","text_en":"Les corps polaires seulement","is_correct":false},{"text_fr":"Dans les spermatozoïdes et les cellules des ovules","text_en":"Dans les spermatozoïdes et les cellules des ovules","is_correct":true},{"text_fr":"Dans la production du sperme seulement","text_en":"Dans la production du sperme seulement","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Ce que vous voyez lorsque vous regardez est un moyen d’identifier :","text_en":"Ce que vous voyez lorsque vous regardez est un moyen d’identifier :","explanation_fr":"Le phénotype rassemble l'ensemble des caractéristiques observées ou mesurables chez un organisme.","explanation_en":"Le phénotype rassemble l'ensemble des caractéristiques observées ou mesurables chez un organisme.","options":[{"text_fr":"Le phénotype","text_en":"Le phénotype","is_correct":true},{"text_fr":"Le génotype","text_en":"Le génotype","is_correct":false},{"text_fr":"Le génome","text_en":"Le génome","is_correct":false},{"text_fr":"L’allotype","text_en":"L’allotype","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"À quel processus est due une quelconque différence génétique dans un clone ?","text_en":"À quel processus est due une quelconque différence génétique dans un clone ?","explanation_fr":"Un clone étant un ensemble d'individus issus de mitoses successives identiques, seule une mutation de séquence peut générer une différence génétique.","explanation_en":"Un clone étant un ensemble d'individus issus de mitoses successives identiques, seule une mutation de séquence peut générer une différence génétiqu