sébacées","is_correct":true},{"text_fr":"Les terminaisons nerveuses","text_en":"Les terminaisons nerveuses","is_correct":false},{"text_fr":"Les muscles érecteurs","text_en":"Les muscles érecteurs","is_correct":false},{"text_fr":"Les capillaires sanguins","text_en":"Les capillaires sanguins","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Les sacs alvéolaires et les tubes contournés des néphrons sont semblables car :","text_en":"Les sacs alvéolaires et les tubes contournés des néphrons sont semblables car :","explanation_fr":"Les unités fonctionnelles pulmonaires (alvéoles) et rénales (néphrons) ont toutes deux un réseau capillaire sanguin extrêmement développé pour permettre les échanges.","explanation_en":"Les unités fonctionnelles pulmonaires (alvéoles) et rénales (néphrons) ont toutes deux un réseau capillaire sanguin extrêmement développé pour permettre les échanges.","options":[{"text_fr":"Les deux ont un approvisionnement sanguin riche","text_en":"Les deux ont un approvisionnement sanguin riche","is_correct":true},{"text_fr":"Les deux ont des cellules couvertes de cils","text_en":"Les deux ont des cellules couvertes de cils","is_correct":false},{"text_fr":"Les deux sont librement perméables aux substances dissoutes","text_en":"Les deux sont librement perméables aux substances dissoutes","is_correct":false},{"text_fr":"Les deux ont des cellules avec un taux de métabolisme élevé","text_en":"Les deux ont des cellules avec un taux de métabolisme élevé","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Quel est le processus par lequel les matières sont renvoyées dans le sang à partir du liquide dans les néphrons ?","text_en":"Quel est le processus par lequel les matières sont renvoyées dans le sang à partir du liquide dans les néphrons ?","explanation_fr":"La réabsorption tubulaire renvoie les molécules d'eau et de solutés de la lumière du néphron vers le sang.","explanation_en":"La réabsorption tubulaire renvoie les molécules d'eau et de solutés de la lumière du néphron vers le sang.","options":[{"text_fr":"La filtration","text_en":"La filtration","is_correct":false},{"text_fr":"L’ultrafiltration","text_en":"L’ultrafiltration","is_correct":false},{"text_fr":"La réabsorption","text_en":"La réabsorption","is_correct":true},{"text_fr":"La sécrétion","text_en":"La sécrétion","is_correct":false},{"text_fr":"La diffusion","text_en":"La diffusion","is_correct":false}]},{"difficulty":"medium","text_fr":"Quel est le nom de la structure qui achemine le liquide du rein à la vessie ?","text_en":"Quel est le nom de la structure qui achemine le liquide du rein à la vessie ?","explanation_fr":"L'uretère est le canal excréteur conduisant l'urine définitive du bassinet du rein jusqu'à la vessie.","explanation_en":"L'uretère est le canal excréteur conduisant l'urine définitive du bassinet du rein jusqu'à la vessie.","options":[{"text_fr":"Le bassinet","text_en":"Le bassinet","is_correct":false},{"text_fr":"L’uretère","text_en":"L’uretère","is_correct":true},{"text_fr":"Le conduit collecteur","text_en":"Le conduit collecteur","is_correct":false},{"text_fr":"L’urètre","text_en":"L’urètre","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Laquelle des propositions suivantes décrivent le mieux des fonctions du sang ?","text_en":"Laquelle des propositions suivantes décrivent le mieux des fonctions du sang ?","explanation_fr":"La fonction essentielle du système circulatoire sanguin est la distribution des gaz respiratoires et des nutriments aux tissus métaboliques.","explanation_en":"La fonction essentielle du système circulatoire sanguin est la distribution des gaz respiratoires et des nutriments aux tissus métaboliques.","options":[{"text_fr":"Il aide à donner au corps humain une structure et un soutien (appui)","text_en":"Il aide à donner au corps humain une structure et un soutien (appui)","is_correct":false},{"text_fr":"Il aide à excréter les déchets via le système urinaire","text_en":"Il aide à excréter les déchets via le système urinaire","is_correct":false},{"text_fr":"Il transporte l’oxygène dans poumons et les nutriments du système digestif aux cellules","text_en":"Il transporte l’oxygène dans poumons et les nutriments du système digestif aux cellules","is_correct":true},{"text_fr":"Il aide dans la formation des caractères sexuels secondaires y compris la production du sperme et des ovules","text_en":"Il aide dans la formation des caractères sexuels secondaires y compris la production du sperme et des ovules","is_correct":false},{"text_fr":"Toutes les réponses ci-dessus","text_en":"Toutes les réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Quels vaisseaux sanguins sont directement impliqués à emporter le sang du Cœur ?","text_en":"Quels vaisseaux sanguins sont directement impliqués à emporter le sang du Cœur ?","explanation_fr":"Les artères sont par définition les vaisseaux efférents qui conduisent le sang depuis le cœur vers les organes.","explanation_en":"Les artères sont par définition les vaisseaux efférents qui conduisent le sang depuis le cœur vers les organes.","options":[{"text_fr":"Les veines","text_en":"Les veines","is_correct":false},{"text_fr":"Les veinules","text_en":"Les veinules","is_correct":false},{"text_fr":"Les artères","text_en":"Les artères","is_correct":true},{"text_fr":"Les capillaires","text_en":"Les capillaires","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Quelle est l’énergie stockée nécessaire pour faire marcher la pompe sodium-potassium ?","text_en":"Quelle est l’énergie stockée nécessaire pour faire marcher la pompe sodium-potassium ?","explanation_fr":"La pompe Na+K+ est une ATPase qui consomme l'énergie issue de l'hydrolyse de l'ATP pour effectuer son transport actif.","explanation_en":"La pompe Na+K+ est une ATPase qui consomme l'énergie issue de l'hydrolyse de l'ATP pour effectuer son transport actif.","options":[{"text_fr":"ATP","text_en":"ATP","is_correct":true},{"text_fr":"Kinésique","text_en":"Kinésique","is_correct":false},{"text_fr":"Énergie de mouvement","text_en":"Énergie de mouvement","is_correct":false},{"text_fr":"B et C à la fois","text_en":"B et C à la fois","is_correct":false},{"text_fr":"A et B à la fois","text_en":"A et B à la fois","is_correct":false}]},{"difficulty":"medium","text_fr":"Laquelle des phrases suivantes décrit le mieux la structure de la membrane cellulaire ?","text_en":"Laquelle des phrases suivantes décrit le mieux la structure de la membrane cellulaire ?","explanation_fr":"C'est le principe du modèle de la mosaïque fluide : des protéines enchâssées ou flottantes au sein d'une matrice phospholipidique en double couche.","explanation_en":"C'est le principe du modèle de la mosaïque fluide : des protéines enchâssées ou flottantes au sein d'une matrice phospholipidique en double couche.","options":[{"text_fr":"Deux couches de protéines avec les couches lipides entre les couches des protéines","text_en":"Deux couches de protéines avec les couches lipides entre les couches des protéines","is_correct":false},{"text_fr":"Deux couches de lipides avec les protéines entre les couches de lipides","text_en":"Deux couches de lipides avec les protéines entre les couches de lipides","is_correct":false},{"text_fr":"Une couche double des molécules de lipides formant une matrice avec des molécules de protéines suspendues dans la matrice des lipides","text_en":"Une couche double des molécules de lipides formant une matrice avec des molécules de protéines suspendues dans la matrice des lipides","is_correct":true},{"text_fr":"Une seule couche des protéines à l’extérieur et une seule couche des lipides à l’intérieur","text_en":"Une seule couche des protéines à l’extérieur et une seule couche des lipides à l’intérieur","is_correct":false},{"text_fr":"Aucune des réponses ci-dessus","text_en":"Aucune des réponses ci-dessus","is_correct":false}]},{"difficulty":"medium","text_fr":"Une artère a une paroi plus épaisse qu’une veine parce que l’artère","text_en":"Une artère a une paroi plus épaisse qu’une veine parce que l’artère","explanation_fr":"Les artères possèdent une média musculo-élastique particulièrement développée pour amortir et supporter la pression d'éjection systolique du cœur.","explanation_en":"Les artères possèdent une média musculo-élastique particulièrement développée pour amortir et supporter la pression d'éjection systolique du cœur.","options":[{"text_fr":"Doit se contracter de manière rythmique pour pomper le sang en avant","text_en":"Doit se contracter de manière rythmique pour pomper le sang en avant","is_correct":false},{"text_fr":"Doit résister à la pression artérielle élevée","text_en":"Doit résister à la pression artérielle élevée","is_correct":true},{"text_fr":"N’a pas de valve pour prévenir un reflux du sang","text_en":"N’a pas de valve pour prévenir un reflux du sang","is_correct":false},{"text_fr":"Doit se contracter de manière rythmique pour pomper le sang en avant et n’a pas de valves pour prévenir un reflux du sang","text_en":"Doit se contracter de manière rythmique pour pomper le sang en avant et n’a pas de valves pour prévenir un reflux du sang","is_correct":false},{"text_fr":"N’a pas de valve pour prévenir le reflux du sang et doit résister à la pression artérielle élevée","text_en":"N’a pas de valve pour prévenir le reflux du sang et doit résister à la pression artérielle élevée","is_correct":false}]}]}$j$::jsonb;
  paper jsonb := spec->'paper';
  v_quiz_id uuid := (paper->>'quizId')::uuid;
  qn jsonb;
  opt jsonb;
  v_question_id uuid;
  v_pos int;
  c_pos int;
begin
  -- 2) The paper's quiz (standalone).
  if not exists (select 1 from public.quizzes where id = v_quiz_id) then
    insert into public.quizzes (id, lesson_id, mock_exam_id, title_fr, title_en, difficulty, passing_score, session_size)
    values (v_quiz_id, null, null, paper->>'title_fr', paper->>'title_en', 'medium', 50,
            jsonb_array_length(spec->'questions'));
  end if;

  -- 3) Questions + choices (idempotent by text_fr within this quiz).
  v_pos := coalesce((select max(position) + 1 from public.questions where quiz_id = v_quiz_id), 0);
  for qn in select value from jsonb_array_elements(spec->'questions')
  loop
    if exists (select 1 from public.questions where quiz_id = v_quiz_id and text_fr = qn->>'text_fr') then
      continue;
    end if;
    insert into public.questions (quiz_id, text_fr, text_en, explanation_fr, explanation_en, difficulty, ai_generated, position)
    values (
      v_quiz_id, qn->>'text_fr', qn->>'text_en',
      coalesce(qn->>'explanation_fr', ''), coalesce(qn->>'explanation_en', ''),
      coalesce((qn->>'difficulty')::difficulty_level, 'medium'), false, v_pos
    )
    returning id into v_question_id;
    v_pos := v_pos + 1;

    c_pos := 0;
    for opt in select value from jsonb_array_elements(qn->'options')
    loop
      insert into public.choices (question_id, text_fr, text_en, is_correct, position)
      values (v_question_id, opt->>'text_fr', opt->>'text_en', coalesce((opt->>'is_correct')::boolean, false), c_pos);
      c_pos := c_pos + 1;
    end loop;
  end loop;

  -- 4) Shop item (past_paper) pointing at the paper's quiz via reference_id.
  if exists (select 1 from public.shop_items where key = paper->>'shopKey') then
    update public.shop_items
      set reference_id = v_quiz_id, active = true
      where key = paper->>'shopKey';
  else
    insert into public.shop_items (key, name_fr, name_en, price_coins, item_type, reference_id, is_limited, active)
    values (paper->>'shopKey', paper->>'title_fr', paper->>'title_en', (paper->>'priceCoins')::int,
            'past_paper', v_quiz_id, false, true);
  end if;
end $$;
